def bestTripleSum(nums, limit):
    a = sorted(nums)
    n = len(a)
    best = -1
    for i in range(n - 2):
        if a[i] + a[i + 1] + a[i + 2] > limit:
            break
        lo, hi = i + 1, n - 1
        while lo < hi:
            s = a[i] + a[lo] + a[hi]
            if s <= limit:
                if s > best:
                    best = s
                    if best == limit:
                        return best
                lo += 1
            else:
                hi -= 1
    return best
